# 2. __init_subclass__ registry (no metaclass needed)
class Processor:
    registry = {}
    def __init_subclass__(cls, /, key=None, **kw):
        super().__init_subclass__(**kw)
        Processor.registry[key or cls.__name__.lower()] = cls

class Csv(Processor, key="csv"): pass
class Excel(Processor): pass
print(sorted(Processor.registry))
```

